// Prepare l'appel Gemini. Ce noeud ne fait aucun appel : il assemble le prompt
// et le corps de la requete, pour que le prompt reste lisible ici plutot que
// noye dans une expression du noeud HTTP.
//
// Le profil sante n'entre PAS dans le prompt : c'est l'API qui l'applique, et
// le LLM n'a pas a raisonner sur la sante (ARCHITECTURE_V2.md §7).
const e = $input.first().json;

function historique(brut) {
  if (Array.isArray(brut)) return brut;
  if (typeof brut === 'string') {
    try { const v = JSON.parse(brut); return Array.isArray(v) ? v : []; } catch (_) { return []; }
  }
  return [];
}

const tours = historique(e.session_history)
  .slice(-5)
  .map((t) => `${t.role === 'bot' ? 'Assistant' : 'Utilisateur'} : ${t.text}`)
  .join('\n');

const invite = [
  `Langue enregistree de l'utilisateur : ${e.language || 'fr'}.`,
  tours ? `Derniers echanges :\n${tours}` : "Premier echange de la session.",
  `Message a analyser :\n${e.text || ''}`,
].join('\n\n');

const consigne = [
  "Tu es l'aiguilleur de NutriSenegal, un assistant nutritionnel senegalais.",
  "Tu ne reponds jamais a l'utilisateur : tu classes son message et tu en extrais les ingredients.",
  '',
  'Intentions :',
  '- analyze_dish : il decrit un plat ou un repas, present ou passe, et veut savoir ce qu\'il vaut.',
  '- recommend : il demande quoi manger.',
  '- alternatives : il demande par quoi remplacer un plat.',
  '- dish_details : il demande la composition d\'un plat.',
  '- update_profile : il veut modifier son profil (maladies, allergies, poids, langue, audio).',
  '- help : il demande de l\'aide ou ce que tu sais faire.',
  '- other : salutation, hors sujet, ou message incomprehensible.',
  '',
  'Regles strictes :',
  '1. name_fr est TOUJOURS le nom francais courant de l\'ingredient, meme si le message est en wolof',
  '   ou en anglais : la base de donnees et le moteur de regles sont en francais.',
  '   name_raw garde le mot tel qu\'ecrit par l\'utilisateur.',
  '2. Tu n\'inventes aucun ingredient : seuls ceux que le message mentionne.',
  '   Le nom d\'un plat connu ne suffit pas a deduire sa recette — laisse ingredients vide',
  '   et renseigne dish_name, la base retrouvera la composition.',
  '3. quantity et unit ne sont renseignes que s\'ils sont dits. Sinon null.',
  '4. language est la langue du MESSAGE, pas celle du profil.',
  '5. confidence est ta certitude reelle sur l\'intention ET sur les ingredients.',
  '   En dessous de 0.6 le systeme bascule sur une analyse de repli et demande',
  '   confirmation : une valeur honnete vaut mieux qu\'une valeur flatteuse.',
].join('\n');

const schema = {
  type: 'object',
  properties: {
    language: { type: 'string', enum: ['fr', 'wo', 'en'] },
    intent: {
      type: 'string',
      enum: ['analyze_dish', 'recommend', 'alternatives', 'dish_details', 'update_profile', 'help', 'other'],
    },
    dish_name: { type: 'string', nullable: true },
    ingredients: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name_fr: { type: 'string' },
          name_raw: { type: 'string' },
          quantity: { type: 'number', nullable: true },
          unit: { type: 'string', nullable: true },
        },
        required: ['name_fr'],
      },
    },
    meal_type: { type: 'string', enum: ['breakfast', 'lunch', 'dinner'], nullable: true },
    confidence: { type: 'number' },
  },
  required: ['language', 'intent', 'confidence'],
};

return [{
  json: {
    ...e,
    gemini_body: {
      systemInstruction: { parts: [{ text: consigne }] },
      contents: [{ role: 'user', parts: [{ text: invite }] }],
      generationConfig: {
        // Temperature basse et sortie contrainte : pas de texte libre ici (§4.2).
        temperature: 0.2,
        responseMimeType: 'application/json',
        responseSchema: schema,
      },
    },
  },
}];

// Lit la sortie Gemini et decide si elle est exploitable.
//
// Le noeud HTTP est en « continue on error » : une panne Gemini arrive ici
// comme un item d'erreur, pas comme un echec de workflow. C'est ce qui permet
// le repli sur /analyze-menu (spaCy + rapidfuzz), qui ne depend d'aucun
// service externe — decision 4 du §11.
const base = $('Contexte NLU').first().json;
const reponse = $input.first().json;

const INTENTS = ['analyze_dish', 'recommend', 'alternatives', 'dish_details', 'update_profile', 'help', 'other'];
const SEUIL = 0.6;

let brut = null;
let erreur = null;
try {
  const parts = reponse?.candidates?.[0]?.content?.parts;
  const texte = Array.isArray(parts) ? parts.map((p) => p.text ?? '').join('') : null;
  if (!texte) {
    throw new Error(reponse?.error?.message || reponse?.message || 'reponse Gemini vide ou bloquee');
  }
  brut = JSON.parse(texte);
} catch (e) {
  erreur = String(e?.message ?? e);
}

const confiance = typeof brut?.confidence === 'number' ? brut.confidence : 0;
let intent = INTENTS.includes(brut?.intent) ? brut.intent : 'other';

const nom = typeof brut?.dish_name === 'string' ? brut.dish_name.trim() : '';
const ingredients = Array.isArray(brut?.ingredients)
  ? brut.ingredients.filter((i) => i && typeof i.name_fr === 'string' && i.name_fr.trim())
  : [];

// Deux cas de repli, volontairement distincts :
//   - plus de JSON du tout : Gemini est indisponible, on replie quoi qu'il arrive ;
//   - JSON douteux sur une analyse : /analyze-menu retente l'extraction hors ligne.
// Une salutation mal notee ne merite pas ce detour : elle devient « other ».
const repli = brut === null || (confiance < SEUIL && intent === 'analyze_dish');
if (brut !== null && confiance < SEUIL && intent !== 'analyze_dish') {
  intent = 'other';
}

const sortie = { ...base };
delete sortie.gemini_body;   // le prompt n'a plus a voyager dans les items

return [{
  json: {
    ...sortie,
    nlu: {
      intent,
      language: ['fr', 'wo', 'en'].includes(brut?.language) ? brut.language : (base.language || 'fr'),
      // En deca de 2 caracteres l'API refuse la recherche : autant ne pas la tenter.
      dish_name: nom.length >= 2 ? nom : null,
      ingredients,
      meal_type: ['breakfast', 'lunch', 'dinner'].includes(brut?.meal_type) ? brut.meal_type : null,
      confidence: confiance,
    },
    nlu_ok: !repli,
    nlu_error: erreur,
    // Vrai des que le systeme n'est pas sur de lui : le compositeur ajoute alors
    // une demande de confirmation plutot que de laisser passer (§7).
    needs_confirmation: repli || confiance < SEUIL,
  },
}];

// Rattache le nom prononce a une ligne de `dishes`, si elle existe.
// Aucune correspondance n'est un resultat normal : l'analyse passera alors par
// les ingredients extraits, pas par la fiche du plat.
const base = $('Lire la sortie NLU').first().json;
// `fullResponse` : le corps est sous .body, et l'item existe meme quand la
// liste est vide — c'est tout l'interet ici.
const reponse = $input.first().json;
const resultats = (Array.isArray(reponse?.body) ? reponse.body : []).filter((d) => d && d.id);
const plat = resultats[0] ?? null;

return [{
  json: {
    ...base,
    dish_id: plat ? plat.id : null,
    dish_db_name: plat ? plat.name : null,
  },
}];

// Aucun nom de plat dans le message : les deux branches doivent quand meme
// porter le meme champ, sinon le Switch recoit des items de formes differentes.
return [{ json: { ...$input.first().json, dish_id: null, dish_db_name: null } }];

// Met en forme le JSON de l'API. Provisoire : WF4 reply-composer prendra ce
// role et redigera dans la langue de l'utilisateur.
//
// Regle qui ne changera pas avec WF4 : aucun chiffre n'est recalcule ici. Tout
// ce qui est affiche vient tel quel de la reponse de l'API (§7).
const base = $('Lire la sortie NLU').first().json;
const r = $input.first().json ?? {};
const nlu = base.nlu ?? {};

const PUCES = { safe: '✅', caution: '⚠️', danger: '🚫', critical: '🛑' };

// Telegram refuse tout le message si le Markdown est mal forme. Les noms de
// plats et d'ingredients viennent du LLM ou de l'utilisateur : un « _ » egare
// suffirait a faire echouer sendMessage, donc a ne rien repondre du tout.
// Seule la structure porte le balisage ; les valeurs en sont debarrassees.
function net(valeur) {
  return String(valeur ?? '').replace(/[*_`\[\]]/g, '');
}

function echec(charge) {
  if (charge?.error) return charge.error?.message ?? charge.error?.detail ?? String(charge.error);
  if (charge?.detail) return typeof charge.detail === 'string' ? charge.detail : JSON.stringify(charge.detail);
  return null;
}

function bloc_analyse(a) {
  const lignes = [];
  lignes.push(`${PUCES[a.alert_level] ?? 'ℹ️'} *${net(a.name)}* — ${a.score}/100`);

  const alertes = [...(a.allergen_alerts ?? []), ...(a.disease_alerts ?? [])];
  if (alertes.length) {
    lignes.push('');
    for (const al of alertes) lignes.push(`${PUCES[al.level] ?? '•'} ${net(al.message)}`);
  }

  if (a.recommendations?.length) {
    lignes.push('');
    for (const c of a.recommendations.slice(0, 5)) lignes.push(`• ${net(c)}`);
  }

  const ns = a.nutritional_summary ?? {};
  if (ns.energy_kcal != null) {
    lignes.push('');
    lignes.push(`${Math.round(ns.energy_kcal)} kcal · ${Math.round(ns.protein_g ?? 0)} g de proteines · ${Math.round(ns.carbohydrate_g ?? 0)} g de glucides`);
  }

  if (a.matched_ingredients?.length) {
    lignes.push('');
    lignes.push(`Reconnus : ${a.matched_ingredients.map(net).join(', ')}`);
  }
  if (a.unmatched_ingredients?.length) {
    lignes.push(`Non reconnus : ${a.unmatched_ingredients.map(net).join(', ')}`);
  }
  return lignes.join('\n');
}

let texte;
const probleme = echec(r);

if (typeof r.reply_text === 'string') {
  // Branches sans appel d'API (aide, profil) : le texte est deja pret.
  texte = r.reply_text;
} else if (probleme) {
  // `alternatives` et `dish_details` exigent une fiche en base : sans elle
  // l'API repond « Dish not found », ce qui ne veut rien dire pour l'utilisateur.
  if (nlu.intent === 'analyze_dish') {
    texte = `Je n'ai pas reussi a analyser ce plat.\n\n_${net(probleme)}_\n\nDis-moi ses ingredients, par exemple « riz, poisson, huile, oignon ».`;
  } else if (nlu.intent === 'alternatives' || nlu.intent === 'dish_details') {
    const nomme = nlu.dish_name ? `« ${net(nlu.dish_name)} »` : 'ce plat';
    texte = `Je ne connais pas ${nomme} en base. Essaie un autre nom, ou decris-moi ce qu'il contient.`;
  } else {
    texte = `Je n'ai pas pu traiter la demande.\n\n_${net(probleme)}_`;
  }
} else if (Array.isArray(r.recommendations) && r.count != null) {
  const lignes = ['🍽️ *Suggestions pour toi*', ''];
  for (const d of r.recommendations) {
    lignes.push(`${PUCES[d.alert_level] ?? '•'} *${net(d.dish_name)}* — ${d.score}/100`);
    if (d.reason) lignes.push(`  _${net(d.reason)}_`);
  }
  if (r.personalized_tips?.length) {
    lignes.push('');
    for (const c of r.personalized_tips.slice(0, 3)) lignes.push(`• ${net(c)}`);
  }
  texte = lignes.join('\n');
} else if (r.original_dish_id) {
  const lignes = [`🔄 *A la place de ${net(r.original_dish_name)}* (${r.original_score}/100)`, ''];
  for (const a of r.alternatives ?? []) {
    lignes.push(`${PUCES[a.alert_level] ?? '•'} *${net(a.dish_name)}* — ${a.score}/100`);
    if (a.reason) lignes.push(`  _${net(a.reason)}_`);
  }
  if (!r.alternatives?.length) lignes.push('_Aucune alternative plus adaptee trouvee en base._');
  for (const s of (r.substitution_suggestions ?? []).slice(0, 3)) lignes.push(`• ${net(s)}`);
  texte = lignes.join('\n');
} else if (Array.isArray(r.ingredients) && r.name) {
  const lignes = [`📋 *${net(r.name)}*`];
  if (r.description) lignes.push(`_${net(r.description)}_`);
  lignes.push('');
  for (const i of r.ingredients) {
    lignes.push(`• ${net(i.name)}${i.quantity ? ` — ${i.quantity} ${net(i.unit ?? '')}`.trimEnd() : ''}`);
  }
  texte = lignes.join('\n');
} else if (r.score != null && r.alert_level) {
  texte = bloc_analyse(r);
} else {
  texte = "Je n'ai pas compris la demande. Decris-moi un plat, ou demande-moi une suggestion.";
}

// Confirmation : ni le repli ni un ingredient non reconnu ne doivent passer
// inapercus. Une analyse incomplete presentee comme complete est le pire des
// resultats (§7).
const non_reconnus = r.unmatched_ingredients ?? [];
if (base.needs_confirmation || non_reconnus.length) {
  const raison = non_reconnus.length
    ? `Je n'ai pas reconnu : ${non_reconnus.map(net).join(', ')}.`
    : "Je ne suis pas sur d'avoir bien compris.";
  texte += `\n\n❓ ${raison} Reformule si le compte n'y est pas.`;
}

texte += '\n\n_Ces indications ne remplacent pas l\'avis d\'un professionnel de sante._';

// Historique court : 5 derniers tours, c'est ce que relit le prompt de WF3.
function historique(brut) {
  if (Array.isArray(brut)) return brut;
  if (typeof brut === 'string') {
    try { const v = JSON.parse(brut); return Array.isArray(v) ? v : []; } catch (_) { return []; }
  }
  return [];
}
const tours = [
  ...historique(base.session_history),
  { role: 'user', text: base.text ?? '', lang: nlu.language },
  { role: 'bot', text: texte, lang: base.language },
].slice(-5);

// Derive de langue (§5, WF3.3) : trois tours d'affilee dans une autre langue
// que la preference enregistree, on propose d'en changer.
const LANGUES = { fr: 'francais', wo: 'wolof', en: 'anglais' };
const derniers = tours.filter((t) => t.role === 'user').slice(-3);
const derive = derniers.length === 3
  && derniers.every((t) => t.lang && t.lang !== base.user_language);
if (derive) {
  texte += `\n\n🌍 Tu m'ecris en ${LANGUES[derniers[0].lang] ?? derniers[0].lang}. Veux-tu que je te reponde dans cette langue ? (/langue)`;
  tours[tours.length - 1].text = texte;
}

return [{
  json: {
    telegram_id: base.telegram_id,
    chat_id: base.chat_id,
    user_id: base.user_id,
    language: base.language,
    intent: nlu.intent,
    detected_language: nlu.language,
    confidence: nlu.confidence,
    needs_confirmation: base.needs_confirmation || non_reconnus.length > 0,
    nlu_error: base.nlu_error ?? null,
    history: tours,
    reply_text: texte,
  },
}];
